    if (array.length <= 1) {
        return [...array];
    }

    const first = array[0];
    const last = array[array.length - 1];
    const sum = first + last;

    const sortedArray = [...array].sort((a, b) => {
        if (sum % 2 === 0) {
            // Even sum - sort in descending order
            return b - a;
        } else {
            // Odd sum - sort in ascending order
            return a - b;
        }
    });

    return sortedArray;
};

